ALTER TABLE recetas ADD COLUMN IF NOT EXISTS diagnostico_id UUID REFERENCES diagnosticos(id), ADD COLUMN IF NOT EXISTS indicaciones_generales TEXT, ADD COLUMN IF NOT EXISTS observaciones TEXT, ADD COLUMN IF NOT EXISTS vigente_hasta DATE, ADD COLUMN IF NOT EXISTS estado VARCHAR(20) NOT NULL DEFAULT 'BORRADOR', ADD COLUMN IF NOT EXISTS creado_por UUID REFERENCES usuarios(id), ADD COLUMN IF NOT EXISTS emitido_en TIMESTAMP, ADD COLUMN IF NOT EXISTS actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE detalle_receta ADD COLUMN IF NOT EXISTS principio_activo VARCHAR(180), ADD COLUMN IF NOT EXISTS concentracion VARCHAR(100), ADD COLUMN IF NOT EXISTS forma_farmaceutica VARCHAR(100), ADD COLUMN IF NOT EXISTS cantidad VARCHAR(100);
